from collections import Counter

def least_interval(tasks, n):
    if not tasks:
        return 0
    count = Counter(tasks)
    max_count = max(count.values())
    count_of_max = sum(1 for v in count.values() if v == max_count)
    required = (max_count - 1) * (n + 1) + count_of_max
    total_tasks = len(tasks)
    return max(total_tasks, required)

