    m = len(s)
    n = len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 and j == 0:
                continue  # already initialized to True
            if i == 0:
                if p[j-1] == '*' and j >= 2:
                    dp[i][j] = dp[i][j-2]
                else:
                    dp[i][j] = False
            else:
                if j == 0:
                    dp[i][j] = False
                    continue
                if p[j-1] == '*':
                    if j >= 2:
                        option1 = dp[i][j-2]
                        if s[i-1] == p[j-2] or p[j-2] == '.':
                            option2 = dp[i-1][j]
                        else:
                            option2 = False
                        dp[i][j] = option1 or option2
                    else:
                        dp[i][j] = False
                else:
                    if p[j-1] == '.' or (p[j-1] == s[i-1]):
                        dp[i][j] = dp[i-1][j-1]
                    else:
                        dp[i][j] = False

    return dp[m][n]

