from collections import defaultdict

def longestSubstringWithSameLetters(s, k):
    n = len(s)
    if n == 0:
        return 0

    freq = defaultdict(int)
    left = 0
    max_len = 0
    max_freq = 0

    for right in range(n):
        char = s[right]
        freq[char] += 1

        if freq[char] > max_freq:
            max_freq = freq[char]

        while (right - left + 1) - max_freq > k:
            left_char = s[left]
            freq[left_char] -= 1

            if freq[left_char] == max_freq - 1:
                current_max = 0
                for c in freq:
                    if freq[c] > current_max:
                        current_max = freq[c]
                max_freq = current_max

            left += 1

        current_length = right - left + 1
        if current_length > max_len:
            max_len = current_length

    return max_len

