def balancedParenthesesAndSum(expression):
    """
    Checks if the given expression is balanced and calculates the sum of digits if it is.

    Args:
    expression (str): input string containing digits and parentheses.

    Returns:
    int: sum of digits if the expression is balanced, otherwise -1.
    """
    # Check for balanced parentheses using a stack
    stack = []
    digit_sum = 0

    for char in expression:
        if char.isdigit():
            digit_sum += int(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return -1
            stack.pop()

    if stack:
        return -1

    return digit_sum

