from typing import List

def min_completion_time(tasks: List[int]) -> int:
    total_time = sum(tasks)
    half_time = total_time // 2
    n = len(tasks)

    # Using Knapsack DP approach to partition tasks
    dp = [0] * (half_time + 1)

    for task in tasks:
        for t in range(half_time, task - 1, -1):
            dp[t] = max(dp[t], dp[t - task] + task)

    best_partition = dp[half_time]
    return max(best_partition, total_time - best_partition)

